+function update(dt){elapsed+=dt;fireTimer=Math.max(0,fireTimer-dt);flash=Math.max(0,flash-dt);let f=Number(keys.KeyW||keys.ArrowUp)-Number(keys.KeyS||keys.ArrowDown),side=Number(keys.KeyD||keys.ArrowRight)-Number(keys.KeyA||keys.ArrowLeft);if(touchMove){f=-Math.max(-1,Math.min(1,(touchMove.y-touchMove.oy)/45));side=Math.max(-1,Math.min(1,(touchMove.x-touchMove.ox)/45));if(Math.abs(f)+Math.abs(side)<.1){f=-Math.max(-1,Math.min(1,(touchMove.y-touchMove.oy)/45));side=Math.max(-1,Math.min(1,(touchMove.x-touchMove.ox)/45))}}let speed=Math.hypot(p.vx,p.vz),accel=(p.ground?19:7);p.vx+=(Math.sin(p.yaw)*f+Math.cos(p.yaw)*side)*accel*dt;p.vz+=(Math.cos(p.yaw)*f-Math.sin(p.yaw)*side)*accel*dt;let drag=p.ground?.982:.997;p.vx*=Math.pow(drag,dt*60);p.vz*=Math.pow(drag,dt*60);let max=keys.ShiftLeft||keys.ShiftRight?24:16;if(Math.hypot(p.vx,p.vz)>max){let s=max/Math.hypot(p.vx,p.vz);p.vx*=s;p.vz*=s}p.x+=p.vx*dt;p.z+=p.vz*dt;if(p.x>arena)p.x=arena;if(p.x< -arena)p.x=-arena;if(p.z>arena*2)p.z=arena*2;if(p.z< -12)p.z=-12;
